INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2044BKK', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'$$\\frac{x}{7} + 3 > 6$$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20NRY4I', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A factory produces $39$ widgets per hour with $13$ workers. If the factory hires $8$ additional workers and each worker produces widgets at the same individual rate, how many widgets per hour will the factory produce in total?', NULL, $lyceon_json$[{"key":"A","text":"$24$"},{"key":"B","text":"$47$"},{"key":"C","text":"$63$"},{"key":"D","text":"$117$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $63$. Each worker produces $\\frac{39}{13} = 3$ widgets per hour. With $13 + 8 = 21$ workers, the total output is $21 \\times 3 = 63$ widgets per hour. The distractor $24$ comes from computing $8 \\times 3 = 24$, counting only the new workers'' output. The distractor $47$ results from adding the number of new workers to the original output ($39 + 8 = 47$). The distractor $117$ results from incorrectly multiplying $39 \\times 3 = 117$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20XT4KY', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What value of $x$ satisfies the equation $6x + 17 = 53$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$4$"},{"key":"C","text":"$8$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtracting 17 from both sides gives $6x = 36$. Dividing both sides by 6 gives $x = 6$. The value 4 results from an arithmetic slip when dividing 36 by 6 incorrectly. The value 8 comes from subtracting 17 from 53 incorrectly as 48, then dividing by 6. The value 10 results from a sign error, treating 17 as negative when isolating the variable.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21CO7HO', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'A surveyor stands at point $P$ and observes the top of a tower at an angle of elevation $\\alpha$, where $\\tan(\\alpha) = \\frac{3}{8}$. The surveyor then walks $18$ meters directly toward the tower to point $Q$ and observes the top at an angle of elevation $\\beta$, where $\\tan(\\beta) = \\frac{3}{5}$. What is the height of the tower, in meters?', NULL, $lyceon_json$[{"key":"A","text":"$18$"},{"key":"B","text":"$30$"},{"key":"C","text":"$48$"},{"key":"D","text":"$\\frac{27}{4}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Let $h$ be the height of the tower and $d$ be the horizontal distance from point $Q$ to the base of the tower. From point $Q$: $\\tan(\\beta) = \\frac{h}{d} = \\frac{3}{5}$, so $h = \\frac{3d}{5}$. From point $P$: $\\tan(\\alpha) = \\frac{h}{d + 18} = \\frac{3}{8}$, so $h = \\frac{3(d + 18)}{8}$. Setting these equal: $\\frac{3d}{5} = \\frac{3(d + 18)}{8}$. Dividing both sides by $3$: $\\frac{d}{5} = \\frac{d + 18}{8}$. Cross-multiplying: $8d = 5d + 90$, so $3d = 90$ and $d = 30$. Therefore $h = \\frac{3(30)}{5} = 18$ meters. The distractor $30$ comes from reporting the distance $d$ rather than the height. The distractor $48$ results from incorrectly adding $30 + 18$. The distractor $\\frac{27}{4}$ arises from using the $18$-meter walk as the full distance with $\\tan(\\alpha) = \\frac{3}{8}$, computing $\\frac{3}{8} \\times 18 = \\frac{27}{4}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21JM0BW', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'$$8x - 6y = 11$$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM221PUJU', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(2, 13)$ and $(6, 29)$. Which of the following is the equation of this line?', NULL, $lyceon_json$[{"key":"A","text":"$y = -4x + 21$"},{"key":"B","text":"$y = \\frac{1}{4}x + \\frac{25}{2}$"},{"key":"C","text":"$y = 4x - 5$"},{"key":"D","text":"$y = 4x + 5$"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is $y = 4x + 5$. The slope is $\\frac{29 - 13}{6 - 2} = \\frac{16}{4} = 4$. Using point-slope form with $(2, 13)$: $y - 13 = 4(x - 2)$, which simplifies to $y = 4x - 8 + 13 = 4x + 5$. The equation $y = -4x + 21$ uses a negated slope; although it passes through $(2, 13)$, it does not pass through $(6, 29)$. The equation $y = \\frac{1}{4}x + \\frac{25}{2}$ uses the reciprocal of the slope instead of the slope itself. The equation $y = 4x - 5$ has the correct slope but an incorrect $y$-intercept from a sign error when simplifying $-8 + 13$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23NB7HS', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A ceramics studio charges a $\\$13$ membership fee plus $\\$7$ per hour of studio time. A student wants to spend less than $\\$62$ on a single visit. Which inequality represents the number of hours, $h$, of studio time the student can use?', NULL, $lyceon_json$[{"key":"A","text":"$h < 7$"},{"key":"B","text":"$h \\leq 7$"},{"key":"C","text":"$h < 49$"},{"key":"D","text":"$h < \\frac{62}{7}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $h < 7$. The total cost of a visit is $13 + 7h$, and the student wants this to be less than $62$: $13 + 7h < 62$. Subtracting $13$ from both sides gives $7h < 49$, and dividing both sides by $7$ gives $h < 7$. The choice $h \\leq 7$ incorrectly includes the boundary value; at $h = 7$ the cost is exactly $\\$62$, which is not less than $\\$62$. The choice $h < 49$ results from subtracting $13$ but not dividing by $7$. The choice $h < \\frac{62}{7}$ results from dividing $62$ by $7$ without first subtracting the membership fee.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24VPUYD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A health magazine reports that people who eat breakfast daily have lower rates of heart disease than people who skip breakfast. The magazine concludes that eating breakfast prevents heart disease. Which of the following best explains why this conclusion may not be valid?', NULL, $lyceon_json$[{"key":"A","text":"The sample size of the study may have been too small."},{"key":"B","text":"People who eat breakfast may differ from those who skip it in other health-related ways, so the association may not be causal."},{"key":"C","text":"The study should have measured lunch habits instead of breakfast habits."},{"key":"D","text":"Heart disease rates are always decreasing over time, so the result is expected."}]$lyceon_json$::jsonb, 'B', NULL, E'The study is observational — participants were not randomly assigned to eat or skip breakfast. Because of this, confounding variables (such as overall lifestyle, exercise habits, or income) may explain the association between breakfast consumption and lower heart disease rates. Without random assignment, a causal conclusion is not warranted. While sample size can affect precision, it does not address the confounding issue that undermines causation. Measuring lunch habits is irrelevant to the claim about breakfast. The assertion that heart disease rates always decrease over time is unsupported and does not explain the observed association.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25BRAOK', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'$$x + y = 23$$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26I6A64', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'If $f(x) = 7x - 11$, what is the value of $f(4)$?', NULL, $lyceon_json$[{"key":"A","text":"$39$"},{"key":"B","text":"$17$"},{"key":"C","text":"$28$"},{"key":"D","text":"$-17$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $17$. Substituting $x = 4$ into $f(x) = 7x - 11$ gives $f(4) = 7(4) - 11 = 28 - 11 = 17$. The value $39$ results from adding $11$ instead of subtracting it ($28 + 11 = 39$). The value $28$ comes from computing $7(4) = 28$ but not subtracting $11$. The value $-17$ results from a sign error in the final computation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29UR1WF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A shirt originally priced at $\\$85$ is on sale for $\\$68$. What is the percent discount?', NULL, $lyceon_json$[{"key":"A","text":"$17\\%$"},{"key":"B","text":"$20\\%$"},{"key":"C","text":"$25\\%$"},{"key":"D","text":"$80\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $20\\%$. The discount amount is $85 - 68 = 17$ dollars. The percent discount is $\\frac{17}{85} \\times 100 = 20\\%$. The distractor $17\\%$ confuses the dollar discount ($17$) with the percent discount. The distractor $25\\%$ results from dividing the discount by the sale price instead of the original price: $\\frac{17}{68} = 0.25 = 25\\%$. The distractor $80\\%$ comes from computing the fraction of the original price that remains ($\\frac{68}{85} = 0.80$) rather than the fraction that was discounted.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ANKW0M', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'An exponential function $f$ is defined by $f(x) = a \\cdot b^x$, where $a$ and $b$ are positive constants. If $f(1) = 18$ and $f(3) = 162$, what is the value of $a$?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$3$"},{"key":"C","text":"$6$"},{"key":"D","text":"$18$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $6$. From $f(1) = ab = 18$ and $f(3) = ab^3 = 162$, dividing the second equation by the first gives $\\frac{ab^3}{ab} = b^2 = \\frac{162}{18} = 9$, so $b = 3$. Substituting back into $ab = 18$ gives $a = \\frac{18}{3} = 6$. The value $2$ results from an arithmetic error in the division step. The value $3$ confuses $b$ with $a$, returning the base instead of the coefficient. The value $18$ mistakes $f(1)$ for $a$, ignoring the factor of $b$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BFONDY', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $h$ is defined by $h(x) = -3(x - 5)^2(x + 1)$. Which of the following correctly describes the end behavior of the graph of $h$ and the number of distinct $x$-intercepts?', NULL, $lyceon_json$[{"key":"A","text":"As $x \\to \\infty$, $h(x) \\to -\\infty$; as $x \\to -\\infty$, $h(x) \\to \\infty$. The graph has $2$ distinct $x$-intercepts."},{"key":"B","text":"As $x \\to \\infty$, $h(x) \\to \\infty$; as $x \\to -\\infty$, $h(x) \\to -\\infty$. The graph has $2$ distinct $x$-intercepts."},{"key":"C","text":"As $x \\to \\infty$, $h(x) \\to -\\infty$; as $x \\to -\\infty$, $h(x) \\to \\infty$. The graph has $3$ distinct $x$-intercepts."},{"key":"D","text":"As $x \\to \\infty$, $h(x) \\to \\infty$; as $x \\to -\\infty$, $h(x) \\to -\\infty$. The graph has $3$ distinct $x$-intercepts."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer describes end behavior where $h(x) \\to -\\infty$ as $x \\to \\infty$ and $h(x) \\to \\infty$ as $x \\to -\\infty$, with $2$ distinct $x$-intercepts. The leading term of $h(x) = -3(x-5)^2(x+1)$ is $-3x^3$, which has a negative leading coefficient and odd degree, so the function rises to the left and falls to the right. The $x$-intercepts occur at $x = 5$ (a repeated root with multiplicity $2$, where the graph touches but does not cross the axis) and $x = -1$, giving $2$ distinct intercepts. The choice with reversed end behavior results from ignoring the negative leading coefficient. The choices listing $3$ distinct intercepts incorrectly count the repeated root at $x = 5$ as though multiplicity $2$ produces two separate intercepts.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C58A21', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'A line is perpendicular to the line $3x - 7y = 14$ and passes through the point $(5, -2)$. What is the $y$-intercept of this line? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '29/3', ARRAY['29/3', '9.666', '9.667'], E'First, rewrite $3x - 7y = 14$ in slope-intercept form: $y = \\frac{3}{7}x - 2$, so the slope is $\\frac{3}{7}$. A perpendicular line has slope equal to the negative reciprocal, which is $-\\frac{7}{3}$. Using the point $(5, -2)$ in point-slope form: $y - (-2) = -\\frac{7}{3}(x - 5)$, giving $y + 2 = -\\frac{7}{3}x + \\frac{35}{3}$. Subtracting $2$ (i.e., $\\frac{6}{3}$) from both sides yields $y = -\\frac{7}{3}x + \\frac{29}{3}$. The $y$-intercept is $\\frac{29}{3}$. A common error is using $\\frac{3}{7}$ (the original slope) rather than the negative reciprocal, or making a sign error when computing the perpendicular slope.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CF4425', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the sum of the solutions to $x^2 - 11x + 28 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'By Vieta''s formulas, the sum of the solutions to $x^2 - 11x + 28 = 0$ is $11$ (the negation of the coefficient of $x$ when the leading coefficient is $1$). This can also be verified by factoring: $x^2 - 11x + 28 = (x - 4)(x - 7) = 0$, so $x = 4$ or $x = 7$, and $4 + 7 = 11$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CMSTSY', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $5x + 4y = 28$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$-7$"},{"key":"C","text":"$28$"},{"key":"D","text":"$\\frac{28}{5}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $7$. To find the $y$-intercept, set $x = 0$: $5(0) + 4y = 28$, so $4y = 28$ and $y = 7$. The value $-7$ results from a sign error when isolating $y$. The value $28$ comes from reading the constant on the right side without dividing by the coefficient of $y$. The value $\\frac{28}{5}$ results from finding the $x$-intercept (setting $y = 0$) instead of the $y$-intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CPD2EO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A spinner is divided into $10$ equal sections: $3$ are labeled red, $4$ are labeled blue, and $3$ are labeled yellow. If the spinner is spun once, what is the probability that it lands on blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{2}{5}$"},{"key":"B","text":"$\\frac{3}{10}$"},{"key":"C","text":"$\\frac{4}{7}$"},{"key":"D","text":"$\\frac{2}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'There are 10 equal sections total, and 4 are labeled blue. The probability of landing on blue is $\\frac{4}{10} = \\frac{2}{5}$. The fraction $\\frac{3}{10}$ gives the probability of landing on red or yellow, misreading which color was asked about. The fraction $\\frac{4}{7}$ incorrectly excludes the yellow sections from the total, dividing blue sections by only red plus blue. The fraction $\\frac{2}{3}$ results from an arithmetic error in simplifying.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DQB2SU', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'$$4x + 3y = 47$$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E8V58T', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'The line of best fit for a dataset relating hours of training ($x$) to assembly time in minutes ($y$) is $y = -3.2x + 58$. Which of the following best describes the meaning of the slope?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour of training, the predicted assembly time increases by $3.2$ minutes."},{"key":"B","text":"For each additional hour of training, the predicted assembly time decreases by $3.2$ minutes."},{"key":"C","text":"For each additional minute of assembly time, the predicted hours of training decreases by $3.2$ hours."},{"key":"D","text":"The predicted assembly time is $-3.2$ minutes when training hours is $0$."}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is the statement that each additional hour of training decreases predicted assembly time by $3.2$ minutes. The slope of $-3.2$ means that for every $1$-unit increase in $x$ (hours of training), $y$ (assembly time) changes by $-3.2$ minutes — a decrease. The distractor claiming an increase of $3.2$ minutes ignores the negative sign. The distractor reversing the roles of $x$ and $y$ misinterprets slope as the change in $x$ per unit change in $y$. The distractor about the value at $x = 0$ confuses the slope with the $y$-intercept.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EQJ6TX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of $400$ households in a county and finds that the mean monthly electricity bill is $\\$137$ with a margin of error of $\\$11$ at a $95\\%$ confidence level. Which of the following conclusions is best supported by this data?', NULL, $lyceon_json$[{"key":"A","text":"$95\\%$ of all households in the county have monthly electricity bills between $\\$126$ and $\\$148$."},{"key":"B","text":"The researcher is $95\\%$ confident that the mean monthly electricity bill for all households in the county is between $\\$126$ and $\\$148$."},{"key":"C","text":"If the survey is repeated, $95\\%$ of households sampled will have bills between $\\$126$ and $\\$148$."},{"key":"D","text":"Exactly $95\\%$ of samples of $400$ households will have a mean bill of $\\$137$."}]$lyceon_json$::jsonb, 'B', NULL, E'The confidence interval $\\$137 \\pm \\$11$, or $\\$126$ to $\\$148$, provides a range of plausible values for the population mean, not for individual values. The statement that $95\\%$ of all households fall in that range confuses a confidence interval for the mean with a range for individual data points. The claim about $95\\%$ of sampled households falling in the range makes the same error applied to future samples. The claim that $95\\%$ of samples yield a mean of exactly $\\$137$ misunderstands both sampling variability and confidence levels.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FA8CO7', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are taken from the same population. Sample A consists of $150$ observations and produces a $95\\%$ confidence interval of $(41.3, 48.7)$ for the population mean. Sample B consists of $600$ observations and produces a $95\\%$ confidence interval of $(43.1, 46.5)$. Which of the following statements is true?', NULL, $lyceon_json$[{"key":"A","text":"Sample B's interval is narrower because increasing the sample size decreases the margin of error."},{"key":"B","text":"Sample B's interval is narrower because the population standard deviation decreased between the two samples."},{"key":"C","text":"The two intervals must overlap, so the population mean is between $43.1$ and $46.5$."},{"key":"D","text":"Because the intervals have different centers, at least one of the samples is biased."}]$lyceon_json$::jsonb, 'A', NULL, E'The margin of error for a confidence interval is proportional to $\\frac{1}{\\sqrt{n}}$, where $n$ is the sample size. Quadrupling the sample size from $150$ to $600$ cuts the margin of error roughly in half, which explains why Sample B''s interval $(43.1, 46.5)$ is narrower than Sample A''s $(41.3, 48.7)$. The population standard deviation is a fixed property of the population and does not change between samples. While the two intervals do overlap, one cannot conclude the population mean must lie in the narrower interval — it is plausible to be anywhere in either interval''s range. Different sample means from different random samples are expected due to sampling variability and do not indicate bias.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G61ULW', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'The linear function $h$ satisfies $h(3) = 19$ and $h(11) = -5$. What is the value of $h(0)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '28', ARRAY['28'], E'The slope of $h$ is $\\frac{-5 - 19}{11 - 3} = \\frac{-24}{8} = -3$. Using the point $(3, 19)$ in point-slope form: $h(x) - 19 = -3(x - 3)$, which gives $h(x) = -3x + 9 + 19 = -3x + 28$. Therefore $h(0) = -3(0) + 28 = 28$. To verify: $h(11) = -3(11) + 28 = -33 + 28 = -5$, confirming the function. A common error is computing the slope as $\\frac{-5 - 19}{11 + 3}$ (adding coordinates instead of subtracting), or stopping after finding the slope without determining the $y$-intercept.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GKWA8R', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A right circular cone is inscribed in a hemisphere of radius $9$ so that the base of the cone coincides with the flat face of the hemisphere. What is the volume of the region inside the hemisphere but outside the cone?', NULL, $lyceon_json$[{"key":"A","text":"$243\\pi$"},{"key":"B","text":"$486\\pi$"},{"key":"C","text":"$972\\pi$"},{"key":"D","text":"$729\\pi$"}]$lyceon_json$::jsonb, 'A', NULL, E'The hemisphere has radius $9$. Its volume is $\\frac{2}{3}\\pi r^3 = \\frac{2}{3}\\pi(729) = 486\\pi$. The inscribed cone has the same base (radius $9$) and its apex touches the top of the hemisphere, so its height equals $9$. The cone''s volume is $\\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(81)(9) = 243\\pi$. The region inside the hemisphere but outside the cone has volume $486\\pi - 243\\pi = 243\\pi$. The distractor $486\\pi$ results from computing only the hemisphere volume without subtracting the cone. The distractor $972\\pi$ comes from using the full sphere volume $\\frac{4}{3}\\pi(9)^3 = 972\\pi$ instead of the hemisphere. The distractor $729\\pi$ results from computing $\\pi r^3 = \\pi(9)^3$ using an incorrect formula.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GMBOBF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $250$ voters in a city found that $58\\%$ support a proposed park renovation. The margin of error for the survey is $4$ percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Between $54\\%$ and $62\\%$ of the sampled voters support the renovation."},{"key":"B","text":"Exactly $58\\%$ of all voters in the city support the renovation."},{"key":"C","text":"It is plausible that between $54\\%$ and $62\\%$ of all voters in the city support the renovation."},{"key":"D","text":"If another sample of $250$ voters is taken, exactly $58\\%$ will support the renovation."}]$lyceon_json$::jsonb, 'C', NULL, E'A margin of error of $4$ percentage points means the plausible range for the true population proportion is $58\\% \\pm 4\\%$, or between $54\\%$ and $62\\%$ of all voters in the city. The interpretation that the range applies only to the sampled voters is incorrect because the sample result is already known exactly. Stating that exactly $58\\%$ of all voters support it ignores sampling variability. Claiming that a new sample will yield exactly $58\\%$ misunderstands that different random samples produce different estimates.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HD9BDR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'The number of visitors to a museum over $5$ days was $61$, $73$, $78$, $82$, and $91$. What is the mean number of daily visitors?', NULL, $lyceon_json$[{"key":"A","text":"$73$"},{"key":"B","text":"$77$"},{"key":"C","text":"$78$"},{"key":"D","text":"$82$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $77$. The sum is $61 + 73 + 78 + 82 + 91 = 385$, and the mean is $\\frac{385}{5} = 77$. The distractor $73$ results from an arithmetic slip when adding the values, such as getting a sum of $365$ and dividing by $5$. The distractor $78$ comes from finding the median (the middle value when sorted) instead of the mean. The distractor $82$ results from misreading the question and selecting one of the data values.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IQBKSJ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'The area of a trapezoid is $161$ square centimeters. The two parallel sides have lengths $9$ cm and $14$ cm. What is the height of the trapezoid, in centimeters?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '14', ARRAY['14'], E'The area of a trapezoid is $A = \\frac{1}{2}(b_1 + b_2) \\cdot h$. Substituting the known values: $161 = \\frac{1}{2}(9 + 14) \\cdot h = \\frac{1}{2}(23) \\cdot h = 11.5h$. Solving for $h$: $h = \\frac{161}{11.5} = 14$ cm. A common error is forgetting the factor of $\\frac{1}{2}$ in the formula, which would give $h = \\frac{161}{23} = 7$. Another error is setting up the equation as $161 = (14 - 9) \\cdot h$, using the difference of the bases instead of the sum.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JIVPES', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A school district conducts a study in which $8$ schools voluntarily adopt a new reading curriculum while $12$ other schools continue using the existing curriculum. At the end of the year, students at the schools using the new curriculum score an average of $17$ points higher on a standardized reading test. A district official claims that the new curriculum caused the improvement in scores. Which of the following is the most serious flaw in this claim?', NULL, $lyceon_json$[{"key":"A","text":"The $17$-point difference is too small to be practically meaningful."},{"key":"B","text":"Schools that volunteered to adopt the new curriculum may have had more motivated staff or different student demographics, so the difference may reflect pre-existing advantages rather than the curriculum's effect."},{"key":"C","text":"The study did not include schools from other districts, so the results cannot be generalized."},{"key":"D","text":"The study should have used a margin of error to determine whether the $17$-point difference is significant."}]$lyceon_json$::jsonb, 'B', NULL, E'Because schools voluntarily chose to adopt the new curriculum rather than being randomly assigned, this is an observational comparison, not a controlled experiment. Schools that volunteered may differ systematically from those that did not — for example, they may have more engaged administrators, higher funding, or different student populations. These confounding factors make it impossible to attribute the $17$-point difference to the curriculum alone. Whether the difference is practically meaningful does not address the causal validity of the claim. Generalizability to other districts is a separate concern from internal validity. While statistical significance testing is useful, it does not resolve the fundamental confounding problem created by self-selection.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JS1VIX', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In a right triangle, one leg measures $11$ and the hypotenuse measures $\\sqrt{290}$. What is the length of the other leg?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'By the Pythagorean theorem, if the legs are $a$ and $b$ and the hypotenuse is $c$, then $a^2 + b^2 = c^2$. Substituting: $11^2 + b^2 = (\\sqrt{290})^2$, so $121 + b^2 = 290$, giving $b^2 = 169$ and $b = 13$. A common error is computing $290 - 121$ incorrectly, and another is forgetting to take the square root of $169$ and reporting $169$ instead.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K3T3XM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangle has a length of $19$ cm and a width of $7$ cm. What is the area of the rectangle, in square centimeters?', NULL, $lyceon_json$[{"key":"A","text":"$133$"},{"key":"B","text":"$52$"},{"key":"C","text":"$26$"},{"key":"D","text":"$126$"}]$lyceon_json$::jsonb, 'A', NULL, E'The area of a rectangle is length times width: $19 \\times 7 = 133$ square centimeters. The distractor $52$ results from computing the perimeter $2(19 + 7) = 52$ instead of the area. The distractor $26$ comes from computing $19 + 7 = 26$, which is the semi-perimeter. The distractor $126$ arises from a multiplication error such as computing $18 \\times 7$ instead of $19 \\times 7$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KTYAOK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $ABC$, $\\angle A = (2x + 14)°$, $\\angle B = (3x - 7)°$, and $\\angle C = (x + 23)°$. The bisector of $\\angle A$ meets side $\\overline{BC}$ at point $D$. What is the measure, in degrees, of $\\angle ADB$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '80', ARRAY['80'], E'First, find $x$ using the triangle angle sum: $(2x + 14) + (3x - 7) + (x + 23) = 180$, which simplifies to $6x + 30 = 180$, so $6x = 150$ and $x = 25$. This gives $\\angle A = 2(25) + 14 = 64°$, $\\angle B = 3(25) - 7 = 68°$, and $\\angle C = 25 + 23 = 48°$. Verify: $64 + 68 + 48 = 180°$. Since $AD$ bisects $\\angle A$, we have $\\angle BAD = \\frac{64}{2} = 32°$. In triangle $ABD$, the angle sum gives $\\angle ADB = 180 - \\angle BAD - \\angle ABD = 180 - 32 - 68 = 80°$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KZ8UKS', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'In a class of $31$ students, each student studies at least one of French or Spanish. Exactly $18$ students study French, and exactly $22$ students study Spanish. Two students are selected at random without replacement. What is the probability that both students study only Spanish?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{13}{31} \\cdot \\frac{12}{30}$"},{"key":"B","text":"$\\frac{22}{31} \\cdot \\frac{21}{30}$"},{"key":"C","text":"$\\frac{9}{31} \\cdot \\frac{8}{30}$"},{"key":"D","text":"$\\frac{13}{31} \\cdot \\frac{13}{31}$"}]$lyceon_json$::jsonb, 'A', NULL, E'By inclusion-exclusion, the number of students studying both languages is $18 + 22 - 31 = 9$. The number studying only Spanish is $22 - 9 = 13$. The probability that the first student selected studies only Spanish is $\\frac{13}{31}$, and given that one only-Spanish student has been removed, the probability the second also studies only Spanish is $\\frac{12}{30}$. The product $\\frac{13}{31} \\cdot \\frac{12}{30}$ is the correct answer. The expression $\\frac{22}{31} \\cdot \\frac{21}{30}$ uses all Spanish students, including those who also study French, rather than only-Spanish students. The expression $\\frac{9}{31} \\cdot \\frac{8}{30}$ confuses the both-languages group ($9$ students) with the only-Spanish group. The expression $\\frac{13}{31} \\cdot \\frac{13}{31}$ fails to account for selection without replacement, keeping the denominator unchanged after the first draw.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L5OSAM', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'The system of equations $x^2 + y^2 = 34$ and $x - y = 2$ has two solutions. What is the product of all $x$-values that satisfy this system?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-15', ARRAY['-15'], E'Substituting $x = y + 2$ into $x^2 + y^2 = 34$ gives $(y+2)^2 + y^2 = 34$, which expands to $y^2 + 4y + 4 + y^2 = 34$, or $2y^2 + 4y - 30 = 0$. Dividing by $2$ yields $y^2 + 2y - 15 = 0$, which factors as $(y+5)(y-3) = 0$. So $y = -5$ or $y = 3$, giving $x = -3$ or $x = 5$. The product of the $x$-values is $(-3)(5) = -15$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LGI3SG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A solution is made by mixing compound X and compound Y in a ratio of $5:11$ by volume. A chemist has $640$ mL of this solution and wants to add more of compound X so that the ratio of compound X to compound Y becomes $3:4$. How many milliliters of compound X should be added?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '130', ARRAY['130'], E'In the original $640$ mL solution with a $5:11$ ratio, compound X accounts for $640 \\times \\frac{5}{16} = 200$ mL and compound Y accounts for $640 \\times \\frac{11}{16} = 440$ mL. Adding $a$ mL of compound X changes the ratio to $\\frac{200 + a}{440} = \\frac{3}{4}$. Solving: $4(200 + a) = 3 \\times 440$, so $800 + 4a = 1320$, giving $4a = 520$ and $a = 130$. A common error is using $640$ as the amount of compound Y, which yields $\\frac{200 + a}{640} = \\frac{3}{4}$, giving $a = 280$. Another error is computing the new total as $640 \\times \\frac{3}{7}$ and subtracting $200$, which gives approximately $74$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MJRWV9', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'If $\\frac{2}{3}(6x - 9) - 5(x - 2) = 4x + 1$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3/5', ARRAY['3/5', '0.6', '.6'], E'Distributing $\\frac{2}{3}$ across $(6x - 9)$ gives $4x - 6$. Distributing $-5$ across $(x - 2)$ gives $-5x + 10$. Combining these on the left side yields $4x - 6 - 5x + 10 = -x + 4$. Setting this equal to the right side: $-x + 4 = 4x + 1$. Adding $x$ to both sides gives $4 = 5x + 1$, and subtracting $1$ gives $3 = 5x$, so $x = \\frac{3}{5}$. A common error is incorrectly distributing $\\frac{2}{3}$ or the negative sign, which leads to an incorrect coefficient on $x$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MKYXTI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'The equation of a circle is $x^2 + y^2 + 2x - 8y - 152 = 0$. A chord of this circle has its midpoint at $(11, 4)$. What is the length of the chord?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '10', ARRAY['10'], E'First, rewrite the equation in standard form by completing the square. Group and complete: $(x^2 + 2x + 1) + (y^2 - 8y + 16) = 152 + 1 + 16$, which gives $(x + 1)^2 + (y - 4)^2 = 169$. The center is $(-1, 4)$ and the radius is $13$. The distance from the center $(-1, 4)$ to the midpoint of the chord $(11, 4)$ is $\\sqrt{(11 - (-1))^2 + (4 - 4)^2} = \\sqrt{144} = 12$. By the perpendicular-from-center-to-chord relationship, the half-length of the chord is $\\sqrt{r^2 - d^2} = \\sqrt{169 - 144} = \\sqrt{25} = 5$. Therefore the full chord length is $2 \\times 5 = 10$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N4KZW3', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'The mean of $9$ numbers is $42$. When three of the numbers — $18$, $27$, and $51$ — are removed, what is the mean of the remaining $6$ numbers?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '47', ARRAY['47'], E'The sum of all $9$ numbers is $9 \\times 42 = 378$. Removing $18$, $27$, and $51$ reduces the sum by $18 + 27 + 51 = 96$, leaving $378 - 96 = 282$. The mean of the remaining $6$ numbers is $\\frac{282}{6} = 47$. A common error is to subtract only the mean of the three removed numbers from $42$: $42 - \\frac{96}{3} = 42 - 32 = 10$. Another error is to divide $282$ by $9$ instead of $6$, yielding approximately $31.3$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OIXJMF', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'In the $xy$-plane, the point $(a, 11)$ lies in the solution region of the system of inequalities below.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OY588E', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A researcher wants to determine whether a new fertilizer increases tomato plant yield. She selects $60$ tomato plants from a greenhouse and randomly assigns $30$ to receive the new fertilizer and $30$ to receive the standard fertilizer. After $8$ weeks, she measures the total weight of tomatoes produced by each plant. Which of the following is the primary advantage of random assignment in this study?', NULL, $lyceon_json$[{"key":"A","text":"It ensures that the sample of $60$ plants is representative of all tomato plants worldwide."},{"key":"B","text":"It eliminates the need to have a control group in the experiment."},{"key":"C","text":"It tends to balance known and unknown confounding variables between the two groups, supporting a causal conclusion."},{"key":"D","text":"It guarantees that the new fertilizer will show a statistically significant effect."}]$lyceon_json$::jsonb, 'C', NULL, E'Random assignment distributes potential confounding variables — such as differences in soil quality, sunlight exposure, or plant health — approximately equally between the treatment and control groups. This allows the researcher to attribute observed differences in yield to the fertilizer rather than to pre-existing differences between groups. Random assignment does not make the sample representative of all tomato plants; that concerns random selection from a population. A control group receiving standard fertilizer is still present and necessary. Random assignment does not guarantee statistical significance — it enables valid causal inference if a significant difference is found.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P3R1WY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of $200$ customers at a bookstore found that $74$ purchased fiction, $53$ purchased nonfiction, and $19$ purchased both fiction and nonfiction. If a customer who purchased fiction is selected at random, what is the probability that this customer also purchased nonfiction?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{19}{200}$"},{"key":"B","text":"$\\frac{19}{53}$"},{"key":"C","text":"$\\frac{19}{74}$"},{"key":"D","text":"$\\frac{55}{200}$"}]$lyceon_json$::jsonb, 'C', NULL, E'This is a conditional probability question. Given that the customer purchased fiction, the sample space is the $74$ fiction purchasers. Of those, $19$ also purchased nonfiction, so the conditional probability is $\\frac{19}{74}$. The result $\\frac{19}{200}$ divides by the total number of customers instead of conditioning on fiction purchasers. The result $\\frac{19}{53}$ incorrectly conditions on nonfiction purchasers rather than fiction purchasers. The result $\\frac{55}{200}$ uses $74 - 19 = 55$ as a numerator over the full sample, confusing the fiction-only count with the conditional probability.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PMB8TI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, $\\sin(\\theta) = \\frac{7}{19}$. What is $\\cos(90° - \\theta)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{19}{7}$"},{"key":"B","text":"$\\frac{7}{19}$"},{"key":"C","text":"$\\frac{12}{19}$"},{"key":"D","text":"$\\frac{7}{12}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The cofunction identity states that $\\cos(90° - \\theta) = \\sin(\\theta)$. Since $\\sin(\\theta) = \\frac{7}{19}$, it follows that $\\cos(90° - \\theta) = \\frac{7}{19}$. The distractor $\\frac{19}{7}$ results from confusing the cosine cofunction with the reciprocal (cosecant). The distractor $\\frac{12}{19}$ comes from incorrectly subtracting the numerator from the denominator to form a new ratio. The distractor $\\frac{7}{12}$ arises from using $19 - 7 = 12$ as a denominator, an error in applying the Pythagorean relationship.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q154T7', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $h$ is defined by $h(x) = (x + 5)^2 - 12$. What is the minimum value of $h(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-12$"},{"key":"B","text":"$-5$"},{"key":"C","text":"$5$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'A', NULL, E'The function $h(x) = (x + 5)^2 - 12$ is in vertex form $a(x - h)^2 + k$, where the vertex is at $(-5, -12)$. Since $a = 1 > 0$, the parabola opens upward and the minimum value is $k = -12$. The value $-5$ confuses the $x$-coordinate of the vertex with the minimum output value. The value $5$ results from dropping the negative sign on the $x$-coordinate. The value $12$ ignores the negative sign on the constant term.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q78ME8', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $(5x + 3)^2 - (5x - 3)^2$?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$30x$"},{"key":"C","text":"$60x$"},{"key":"D","text":"$50x^2 + 18$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $60x$. Expanding $(5x+3)^2 = 25x^2 + 30x + 9$ and $(5x-3)^2 = 25x^2 - 30x + 9$, the difference is $(25x^2 + 30x + 9) - (25x^2 - 30x + 9) = 60x$. Alternatively, using the difference of squares identity $a^2 - b^2 = (a+b)(a-b)$ with $a = 5x+3$ and $b = 5x-3$ gives $(10x)(6) = 60x$. The result $0$ comes from incorrectly assuming the two squares are equal. The result $30x$ comes from only accounting for the cross term in one expansion. The result $50x^2 + 18$ comes from incorrectly adding the expansions instead of subtracting them.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QIUBE3', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $34$. What is the circumference of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$17\\pi$"},{"key":"B","text":"$34\\pi$"},{"key":"C","text":"$68\\pi$"},{"key":"D","text":"$289\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is $C = \\pi d$, where $d$ is the diameter. Substituting $d = 34$ gives $C = 34\\pi$. The distractor $17\\pi$ comes from halving the diameter to get the radius and then using $\\pi r$ instead of $2\\pi r$. The distractor $68\\pi$ results from incorrectly doubling the diameter before multiplying by $\\pi$. The distractor $289\\pi$ comes from using the area formula $\\pi r^2 = \\pi(17)^2 = 289\\pi$ instead of the circumference formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QQPYSZ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'The three interior angles of a triangle measure $47°$, $59°$, and $x°$. What is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$74$"},{"key":"B","text":"$106$"},{"key":"C","text":"$84$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sum of interior angles in any triangle is $180°$. Setting up the equation: $47 + 59 + x = 180$, so $106 + x = 180$, giving $x = 74$. The distractor $106$ results from computing $47 + 59$ but stopping there without subtracting from $180$. The distractor $84$ comes from an arithmetic error in the subtraction step. The distractor $12$ results from computing $59 - 47$, misinterpreting the question as asking for the difference between the given angles.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SK4JHZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A town''s population increased from $24{,}000$ to $27{,}600$ over one year. What was the percent increase in population?', NULL, $lyceon_json$[{"key":"A","text":"$13\\%$"},{"key":"B","text":"$15\\%$"},{"key":"C","text":"$36\\%$"},{"key":"D","text":"$87\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $15\\%$. The increase is $27{,}600 - 24{,}000 = 3{,}600$. The percent increase is $\\frac{3{,}600}{24{,}000} \\times 100 = 15\\%$. The distractor $13\\%$ results from dividing the increase by the new population instead of the original: $\\frac{3{,}600}{27{,}600} \\approx 13.04\\%$, rounded to $13\\%$. The distractor $36\\%$ comes from seeing $3{,}600$ and misinterpreting it as $36\\%$. The distractor $87\\%$ results from computing $\\frac{24{,}000}{27{,}600} \\approx 86.96\\%$, rounding to $87\\%$, which gives the original as a fraction of the new value rather than the percent change.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TB93R4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A recipe calls for $7$ cups of broth for every $3$ cups of rice. If a chef uses $21$ cups of rice, how many cups of broth are needed?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$28$"},{"key":"C","text":"$49$"},{"key":"D","text":"$63$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $49$. The ratio of broth to rice is $7:3$. Since $21$ cups of rice is $21 \\div 3 = 7$ times the base amount, the broth needed is $7 \\times 7 = 49$ cups. The distractor $9$ results from inverting the ratio and computing $\\frac{3}{7} \\times 21 = 9$. The distractor $28$ comes from an arithmetic slip such as multiplying $7 \\times 4$ instead of $7 \\times 7$. The distractor $63$ results from setting up the proportion incorrectly as $21 \\times 3 = 63$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TLYG6S', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'The price of a laptop was first increased by $20\\%$ and then the new price was decreased by $15\\%$. The final price is what percent of the original price?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '102', ARRAY['102'], E'Let the original price be $P$. After a $20\\%$ increase, the price becomes $1.20P$. After a $15\\%$ decrease from the new price, the final price is $1.20P \\times 0.85 = 1.02P$. Therefore the final price is $102\\%$ of the original price. A common error is to assume the $20\\%$ increase and $15\\%$ decrease cancel to a net $5\\%$ increase, giving $105\\%$. This error arises from adding the percentages directly rather than applying them sequentially as multipliers. Another error is computing $1.20 \\times 1.15 = 1.38$, mistakenly increasing by $15\\%$ instead of decreasing, which gives $138\\%$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V539CJ', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'The function $g$ is defined by $g(x) = -3x + 22$. A biologist uses this model to predict the number of bacteria colonies remaining in a sample $x$ hours after treatment begins. According to this model, by how many colonies does the count decrease each hour?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$22$"},{"key":"C","text":"$-3$"},{"key":"D","text":"$\\frac{22}{3}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $3$. In the function $g(x) = -3x + 22$, the slope is $-3$, which means the colony count decreases by $3$ each hour. The question asks for the amount of decrease, which is the absolute value of the slope. The value $22$ confuses the initial count (the $y$-intercept) with the rate of change. The value $-3$ gives the slope directly but does not correctly answer how many colonies decrease, since a decrease amount is expressed as a positive quantity. The value $\\frac{22}{3}$ results from dividing the $y$-intercept by the magnitude of the slope, which would give the $x$-intercept rather than the rate.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W2362G', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'The line of best fit for a dataset is $y = 8x + 29$, where $x$ is the number of practice sessions and $y$ is the predicted score. What is the predicted score for a student who completes $7$ practice sessions?', NULL, $lyceon_json$[{"key":"A","text":"$37$"},{"key":"B","text":"$56$"},{"key":"C","text":"$85$"},{"key":"D","text":"$93$"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is $85$. Substituting $x = 7$ into the equation gives $y = 8(7) + 29 = 56 + 29 = 85$. The distractor $37$ comes from adding the slope and intercept ($8 + 29 = 37$) without multiplying the slope by $x$. The distractor $56$ results from computing only $8 \\times 7 = 56$ and omitting the intercept. The distractor $93$ comes from substituting $x = 8$ instead of $x = 7$, giving $8(8) + 29 = 93$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WAZOA3', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'What is the positive solution of $2x^2 + 7x - 15 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{3}{2}$"},{"key":"B","text":"$3$"},{"key":"C","text":"$5$"},{"key":"D","text":"$\\frac{5}{2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $\\frac{3}{2}$. Using the quadratic formula, $x = \\frac{-7 \\pm \\sqrt{49 + 120}}{4} = \\frac{-7 \\pm \\sqrt{169}}{4} = \\frac{-7 \\pm 13}{4}$. This gives $x = \\frac{6}{4} = \\frac{3}{2}$ or $x = \\frac{-20}{4} = -5$. The positive solution is $\\frac{3}{2}$. The value $3$ results from not dividing the numerator $6$ by the denominator $4$ correctly. The value $5$ comes from taking the magnitude of the negative solution and ignoring its sign. The value $\\frac{5}{2}$ comes from an arithmetic error in the discriminant calculation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WZ0SH3', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the solution to the equation $\\frac{2x + 11}{3} = 9$?', NULL, $lyceon_json$[{"key":"A","text":"$-1$"},{"key":"B","text":"$8$"},{"key":"C","text":"$-8$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $8$. Multiplying both sides by $3$ gives $2x + 11 = 27$. Subtracting $11$ from both sides yields $2x = 16$, and dividing by $2$ gives $x = 8$. The value $-1$ results from forgetting to multiply by $3$ and solving $2x + 11 = 9$ instead, which gives $2x = -2$ and $x = -1$. The value $-8$ comes from a sign error in the final division. The value $16$ results from stopping at $2x = 16$ without dividing by $2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X9GAVX', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle has center $(-3, 7)$ and passes through the point $(5, 1)$. What is the equation of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$(x + 3)^2 + (y - 7)^2 = 100$"},{"key":"B","text":"$(x - 3)^2 + (y + 7)^2 = 100$"},{"key":"C","text":"$(x + 3)^2 + (y - 7)^2 = 10$"},{"key":"D","text":"$(x - 5)^2 + (y - 1)^2 = 100$"}]$lyceon_json$::jsonb, 'A', NULL, E'The standard form of a circle with center $(h, k)$ and radius $r$ is $(x - h)^2 + (y - k)^2 = r^2$. The radius equals the distance from $(-3, 7)$ to $(5, 1)$: $r = \\sqrt{(5 - (-3))^2 + (1 - 7)^2} = \\sqrt{64 + 36} = \\sqrt{100} = 10$. So $r^2 = 100$ and the equation is $(x + 3)^2 + (y - 7)^2 = 100$. The distractor $(x - 3)^2 + (y + 7)^2 = 100$ uses incorrect signs for the center coordinates. The distractor with $= 10$ on the right side uses $r$ instead of $r^2$. The distractor $(x - 5)^2 + (y - 1)^2 = 100$ incorrectly uses the given point as the center.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XYAJDA', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which expression is equivalent to $\\frac{14x^7}{2x^3}$ for $x \\neq 0$?', NULL, $lyceon_json$[{"key":"A","text":"$7x^4$"},{"key":"B","text":"$7x^{10}$"},{"key":"C","text":"$12x^4$"},{"key":"D","text":"$7x^{\\frac{7}{3}}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $7x^4$. Dividing the coefficients gives $\\frac{14}{2} = 7$, and applying the quotient rule for exponents gives $x^{7-3} = x^4$. The result $7x^{10}$ comes from incorrectly adding the exponents instead of subtracting them. The result $12x^4$ comes from subtracting the coefficients ($14 - 2 = 12$) instead of dividing. The result $7x^{7/3}$ comes from dividing the exponents instead of subtracting them.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YFNIBC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A dataset contains the values $3$, $5$, $7$, $7$, $9$, $11$, and $14$. If the value $14$ is replaced by $35$, which of the following measures of the dataset changes the most?', NULL, $lyceon_json$[{"key":"A","text":"Median"},{"key":"B","text":"Mean"},{"key":"C","text":"Mode"},{"key":"D","text":"Range"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is the range. Originally the range is $14 - 3 = 11$; after the replacement it becomes $35 - 3 = 32$, a change of $21$. The mean changes from $\\frac{56}{7} = 8$ to $\\frac{77}{7} = 11$, a change of $3$. The median remains $7$ because the middle value is unaffected. The mode remains $7$ because replacing $14$ does not affect which value appears most frequently. Since the range changes by $21$ while the mean changes by only $3$ and the median and mode do not change at all, the range changes the most.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZI8Y0A', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the exterior angle at vertex $R$ measures $137°$. If $\\angle P = 53°$, what is the measure, in degrees, of $\\angle Q$?', NULL, $lyceon_json$[{"key":"A","text":"$43$"},{"key":"B","text":"$84$"},{"key":"C","text":"$90$"},{"key":"D","text":"$127$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the Exterior Angle Theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles. Therefore $137 = \\angle P + \\angle Q = 53 + \\angle Q$, which gives $\\angle Q = 137 - 53 = 84$. To verify: the interior angle at $R$ is $180 - 137 = 43°$, and $53 + 84 + 43 = 180°$. The distractor $43$ results from finding the interior angle at $R$ instead of $\\angle Q$. The distractor $90$ comes from an arithmetic error. The distractor $127$ results from incorrectly subtracting $\\angle P$ from $180°$ rather than from the exterior angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZOGNIZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher records the number of hours of sunlight per day ($x$) and the daily energy output of a solar panel in kilowatt-hours ($y$). The least-squares regression line is $y = 0.53x - 1.19$. On a day with $9$ hours of sunlight, the actual energy output was $3.70$ kWh. What is the residual for that observation?', NULL, $lyceon_json$[{"key":"A","text":"$-0.12$"},{"key":"B","text":"$0.12$"},{"key":"C","text":"$3.58$"},{"key":"D","text":"$7.28$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $0.12$. The predicted value is $y = 0.53(9) - 1.19 = 4.77 - 1.19 = 3.58$ kWh. The residual is the actual value minus the predicted value: $3.70 - 3.58 = 0.12$. The distractor $-0.12$ results from computing predicted minus actual ($3.58 - 3.70$), reversing the sign of the residual. The distractor $3.58$ is the predicted value itself, not the residual, reflecting incomplete reasoning that stops before subtracting. The distractor $7.28$ comes from adding the actual and predicted values ($3.70 + 3.58 = 7.28$) instead of subtracting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZS7ODX', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which expression is equivalent to $\\frac{8x^3 + 27}{2x + 3}$?', NULL, $lyceon_json$[{"key":"A","text":"$4x^2 + 6x + 9$"},{"key":"B","text":"$4x^2 - 6x + 9$"},{"key":"C","text":"$4x^2 - 6x - 9$"},{"key":"D","text":"$4x^2 + 9$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $4x^2 - 6x + 9$. Recognizing $8x^3 + 27$ as a sum of cubes $(2x)^3 + 3^3$, the sum of cubes formula $a^3 + b^3 = (a+b)(a^2 - ab + b^2)$ gives $(2x+3)(4x^2 - 6x + 9)$. Dividing by $(2x+3)$ yields $4x^2 - 6x + 9$. The expression $4x^2 + 6x + 9$ results from a sign error in the middle term of the sum of cubes formula. The expression $4x^2 - 6x - 9$ results from an additional sign error on the constant term. The expression $4x^2 + 9$ omits the middle term entirely, treating the numerator as though it factors without a cross term.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2107BD2', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'During the late nineteenth century, the physicist Nikola Tesla envisioned a global system for wireless energy transmission and even constructed a prototype tower on Long Island to test the concept. ________ contemporary engineers have revisited Tesla''s core principles, adapting them to modern microwave and laser-based technologies that can beam power to remote sensors and spacecraft.', $lyceon_json$[{"key":"A","text":"Similarly,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"More than a century later,"},{"key":"D","text":"In other words,"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct transition is "More than a century later," because the passage shifts from Tesla''s work in the late nineteenth century to contemporary engineers'' efforts, and this phrase accurately signals a chronological jump while connecting the two periods. "Similarly," incorrectly implies the two sentences describe parallel but independent phenomena, when the second sentence specifically builds on Tesla''s earlier work. "Nevertheless," suggests an unexpected contrast or concession, but there is no obstacle or contradiction between the two sentences — the modern work extends Tesla''s vision rather than defying it. "In other words," signals a restatement of the same idea, but the second sentence introduces new information about modern adaptations rather than rephrasing Tesla''s original concept.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2114QV3', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'While cataloging specimens at the Belmont Herbarium, botanist Elara Voss identified a fern species previously unrecorded in North American collections. The fronds displayed an unusual pattern of bifurcation at their _______ discovery prompted the herbarium to commission a broader survey of pteridophyte diversity in the southern Appalachian highlands.', $lyceon_json$[{"key":"A","text":"tips, this"},{"key":"B","text":"tips this"},{"key":"C","text":"tips. This"},{"key":"D","text":"tips, in contrast, this"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct choice uses a period to separate two independent clauses: "The fronds displayed an unusual pattern of bifurcation at their tips" and "This discovery prompted the herbarium to commission a broader survey." The comma-only version ("tips, this") creates a comma splice, joining two independent clauses with just a comma. The version without any punctuation ("tips this") produces a run-on sentence. The version with "in contrast" misrepresents the logical relationship between the sentences—the second clause describes a consequence of the discovery, not a contrast with the observation about frond bifurcation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW214Q694', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'In a study of urban noise pollution, acoustic ecologist Reina Sato measured ambient sound levels at 83 intersections in Osaka, Japan, during both weekday rush hours and weekend afternoons. Sato found that average decibel levels at the same intersections were nearly identical across both time periods, despite weekday traffic volumes being roughly 2.5 times higher than weekend volumes. Sato attributed this counterintuitive finding to the prevalence of stop-and-go traffic during rush hours, which produces intermittent bursts of noise separated by relative quiet, whereas weekend traffic flows more continuously. Based on this analysis, Sato concluded that ________', $lyceon_json$[{"key":"A","text":"traffic volume alone is not a reliable predictor of average ambient noise levels at urban intersections."},{"key":"B","text":"urban intersections in Osaka are quieter than intersections in comparable cities worldwide."},{"key":"C","text":"weekend traffic in Osaka poses a greater health risk from noise exposure than weekday traffic."},{"key":"D","text":"stop-and-go traffic patterns have no measurable effect on noise levels at intersections."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that traffic volume alone is not a reliable predictor of average ambient noise levels. The passage establishes that despite 2.5 times higher weekday traffic, average decibel levels were nearly identical to weekend levels, directly supporting the conclusion that volume by itself does not determine noise levels. The choice about Osaka being quieter than comparable cities goes beyond the text, which offers no cross-city comparison. The choice about weekend traffic posing a greater health risk is unsupported; the passage says the noise levels were nearly identical across time periods, not that one was more dangerous. The choice claiming stop-and-go traffic has "no measurable effect" contradicts the passage, which explains that the stop-and-go pattern is precisely what accounts for the unexpected noise equivalence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2156DTV', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'The nineteenth-century architect Elara Vostok rejected the prevailing fashion for ornate facades, instead championing designs that were deliberately ________. Her buildings featured unadorned concrete surfaces and minimal fenestration, a style that puzzled her contemporaries but later influenced the Brutalist movement.', $lyceon_json$[{"key":"A","text":"austere"},{"key":"B","text":"volatile"},{"key":"C","text":"congenial"},{"key":"D","text":"clandestine"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "austere." The passage describes buildings with unadorned surfaces and minimal fenestration that contrasted with ornate facades, so the blank requires a word meaning severely plain or without decoration. "Austere" precisely captures this deliberate plainness. "Volatile" means liable to change rapidly or explosively, which is incoherent as a description of a consistent architectural style. "Congenial" means pleasant or agreeable, which contradicts the passage''s emphasis on designs that puzzled contemporaries by rejecting ornamentation. "Clandestine" means kept secret or hidden, which makes no sense for publicly visible buildings.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21VN3M6', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Marine biologists studying the Pacific deep-sea vents were surprised to find thriving colonies of tubeworms despite the extreme temperatures. The organisms had developed remarkable ________ to the harsh chemical environment, surviving concentrations of hydrogen sulfide that would be lethal to most other species.', $lyceon_json$[{"key":"A","text":"tolerance"},{"key":"B","text":"gratitude"},{"key":"C","text":"nostalgia"},{"key":"D","text":"brevity"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "tolerance." The passage describes organisms that survive extreme chemical conditions, so the blank requires a word meaning the ability to withstand harsh conditions. "Tolerance" precisely conveys this capacity to endure adverse environments. "Gratitude" refers to thankfulness, which is incoherent when describing an organism''s biological relationship to chemicals. "Nostalgia" denotes a sentimental longing for the past, which makes no sense in a biological survival context. "Brevity" means shortness in duration, which produces an incoherent claim about surviving lethal concentrations.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24XSM5D', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Historian Claudia Ferraro has examined correspondence between nineteenth-century Italian silk merchants and their agents in Lyon, France. Ferraro notes that merchants in Como frequently instructed their agents to delay purchases of raw silk cocoons during periods when French buyers were competing aggressively for the same supply. Rather than bidding up prices, the Como merchants would temporarily redirect their operations toward processing lower-grade silk already in their warehouses, returning to the cocoon market only after French demand subsided. Ferraro argues that this pattern reveals ________', $lyceon_json$[{"key":"A","text":"a deliberate strategy of price avoidance in which merchants accepted short-term reductions in product quality to preserve long-term purchasing power."},{"key":"B","text":"the Como merchants' belief that French silk was inherently superior to Italian silk in both quality and durability."},{"key":"C","text":"an inability on the part of Italian merchants to compete financially with their better-capitalized French counterparts."},{"key":"D","text":"widespread cooperation between Italian and French silk merchants to stabilize cocoon prices across European markets."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice describing a deliberate strategy of price avoidance in which merchants accepted short-term quality reductions to preserve long-term purchasing power. The passage describes the merchants deliberately choosing to process lower-grade silk and wait rather than compete on price, which matches the inference of a calculated trade-off. The choice about Como merchants believing French silk was superior is unsupported; the passage discusses market competition for cocoons, not comparative silk quality judgments. The choice about Italian merchants being unable to compete financially imposes a conclusion of incapacity, whereas the passage presents the merchants'' behavior as a strategic choice, not a forced concession. The choice about widespread cooperation between Italian and French merchants contradicts the passage, which describes the two groups as competitors in the cocoon market.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW251IPX4', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Composer Dara Okonkwo drew inspiration from the polyphonic vocal traditions of the Aka people of central _______ layered vocal lines, rhythmic complexity, and an emphasis on communal participation are hallmarks of both the Aka choral style and Okonkwo''s orchestral compositions.', $lyceon_json$[{"key":"A","text":"Africa: layered"},{"key":"B","text":"Africa, layered"},{"key":"C","text":"Africa, for instance, layered"},{"key":"D","text":"Africa layered"}]$lyceon_json$::jsonb, 'A', NULL, E'A colon correctly separates the introductory independent clause from the elaborating clause that specifies the shared characteristics. The second clause explains what traits the two styles share, which is precisely the elaborative relationship a colon signals. The comma-only version ("Africa, layered") produces a comma splice between two independent clauses. The version without punctuation ("Africa layered") creates a run-on sentence. The version with "for instance" mischaracterizes the logical relationship: the second clause does not provide an example of the first clause''s claim but rather identifies the specific features common to both musical traditions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29MNQU5', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Marine biologist Kendra Hollis has spent over a decade studying the symbiotic relationship between cleaner wrasses and larger reef fish. Cleaner wrasses survive by consuming parasites from the skin and gills of groupers, moray eels, and other species that visit designated "cleaning stations" on coral reefs. In a 2023 field study off the coast of Mozambique, Hollis documented that reefs with healthy populations of cleaner wrasses had significantly lower rates of parasitic infection among resident fish compared to reefs where wrasse populations had declined due to overharvesting for the aquarium trade.', $lyceon_json$[{"key":"A","text":"Kendra Hollis's research demonstrates that cleaner wrasse populations play a measurable role in controlling parasitic infections on coral reefs."},{"key":"B","text":"The aquarium trade has caused the decline of cleaner wrasse populations off the coast of Mozambique."},{"key":"C","text":"Groupers and moray eels depend on cleaner wrasses for their survival in reef ecosystems."},{"key":"D","text":"Marine biologists have only recently begun to study symbiotic relationships in coral reef environments."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that Hollis''s research demonstrates cleaner wrasses play a measurable role in controlling parasitic infections on reefs. The passage centers on Hollis''s study and its finding that reefs with healthy wrasse populations had lower parasitic infection rates. The choice focusing on the aquarium trade captures only a supporting detail about why wrasse populations declined, not the passage''s central point. The choice claiming groupers and eels "depend" on wrasses "for their survival" overstates the passage, which discusses parasite reduction rather than species-level survival dependence. The choice suggesting marine biologists have "only recently begun" studying reef symbiosis is unsupported; Hollis herself has studied the topic for over a decade.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2B3KZW2', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researcher''s hypothesis?', E'Entomologist David Kwame has hypothesized that the bioluminescent patterns displayed by fireflies of the species Photinus carolinus serve not only as mating signals but also as a deterrent against predatory spiders. Kwame observed that orb-weaving spiders in the Great Smoky Mountains constructed fewer webs in areas with dense P. carolinus populations during peak flash synchronization events. He proposes that the intense, coordinated light pulses may disrupt the spiders'' ability to detect vibrations from trapped prey on their webs.', $lyceon_json$[{"key":"A","text":"Orb-weaving spiders exposed to artificial light pulses mimicking P. carolinus flash patterns abandon their webs at significantly higher rates than spiders exposed to constant light."},{"key":"B","text":"P. carolinus fireflies are more abundant in forested areas than in open meadows."},{"key":"C","text":"Orb-weaving spiders in the Great Smoky Mountains primarily feed on moths rather than fireflies."},{"key":"D","text":"Several other firefly species also produce synchronized bioluminescent displays during mating seasons."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice about spiders abandoning webs at higher rates when exposed to artificial light pulses mimicking the firefly flash patterns. This directly tests Kwame''s specific hypothesis that the coordinated light pulses deter spiders, by isolating the flash pattern as the variable. The choice about firefly abundance in forests versus meadows addresses habitat distribution, which is unrelated to whether bioluminescence deters spiders. The choice about spiders feeding on moths rather than fireflies concerns diet, not the proposed deterrent mechanism. The choice about other firefly species producing synchronized displays is relevant to firefly biology broadly but does not test whether such displays deter spiders.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BGS5HH', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a research article would most effectively support the claim that mycorrhizal networks facilitate resource sharing between trees of different species?', E'Forestry scientist Amara Okonkwo has argued that mycorrhizal fungal networks — underground webs of fungal filaments connecting the roots of multiple trees — enable interspecies resource transfer in temperate forests. According to Okonkwo, these networks allow surplus carbon and nitrogen to flow from nutrient-rich trees to nutrient-deficient neighbors, even when those neighbors belong to an entirely different species. This process, Okonkwo suggests, may be particularly important during periods of environmental stress, such as prolonged drought, when certain tree species with deeper root systems can indirectly sustain shallower-rooted species nearby.', $lyceon_json$[{"key":"A","text":"\"Isotope-labeled carbon injected into the trunk of a mature Douglas fir was detected within 48 hours in the root tissue of neighboring paper birch saplings connected by a shared Rhizomorphs fungal network.\""},{"key":"B","text":"\"Mycorrhizal networks have been found to extend over 30 meters from a host tree's trunk, making them among the most spatially extensive symbiotic structures in temperate ecosystems.\""},{"key":"C","text":"\"Trees colonized by mycorrhizal fungi exhibit root growth rates approximately 15 percent higher than uncolonized trees of the same species and age.\""},{"key":"D","text":"\"Researchers have identified over 200 species of mycorrhizal fungi in a single hectare of old-growth Pacific Northwest forest, suggesting high fungal biodiversity in these environments.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the quotation about isotope-labeled carbon traveling from a Douglas fir to paper birch saplings via a shared fungal network. This provides direct empirical evidence that resources move between different tree species through mycorrhizal connections, which is exactly the claim under discussion. The quotation about network spatial extent addresses the physical size of mycorrhizal networks but says nothing about resource sharing between species. The quotation about increased root growth rates in colonized trees describes a benefit of fungal colonization to individual trees, not interspecies transfer. The quotation about fungal biodiversity documents species richness of fungi, which does not address whether resources flow between different tree species.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CKY3SK', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Neuroscientist Jia-Wen Chen studied decision-making under uncertainty by presenting participants with a sequence of gambles in which the probabilities of winning were unknown but could be estimated from observed outcomes. Chen found that participants who received feedback after each gamble updated their probability estimates in a manner broadly consistent with Bayesian reasoning when the stakes were low. However, when the potential losses were increased to five times the original amount — with potential gains held constant — the same participants began overweighting recent outcomes and underweighting their accumulated base of evidence. Chen notes that this shift cannot be explained by simple risk aversion, because risk-averse individuals would still update probabilities rationally while simply requiring a higher expected value to gamble. Instead, Chen suggests that elevated loss stakes trigger a qualitatively different cognitive process in which ________', $lyceon_json$[{"key":"A","text":"emotional arousal from potential losses disrupts the evidence-integration mechanisms that ordinarily support Bayesian updating, causing participants to rely on heuristic shortcuts anchored to the most recent observations."},{"key":"B","text":"participants become more attentive to feedback, which enables them to identify subtle patterns in the outcome sequence that they had previously overlooked."},{"key":"C","text":"the participants' underlying risk preferences shift from risk-averse to risk-seeking, leading them to accept gambles they would otherwise reject."},{"key":"D","text":"Bayesian reasoning is an unreliable model of human decision-making regardless of the stakes involved in a given task."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice about emotional arousal from potential losses disrupting evidence-integration mechanisms and causing reliance on heuristic shortcuts anchored to recent observations. The passage establishes that high-loss stakes caused participants to overweight recent outcomes and underweight accumulated evidence, a shift Chen describes as "qualitatively different" from rational updating. This matches an account in which the normal integrative process is disrupted and replaced by a recency-driven heuristic. The choice about participants becoming more attentive and identifying subtle patterns contradicts the passage, which describes a degradation in evidence integration, not an improvement in pattern detection. The choice about risk preferences shifting from averse to seeking contradicts Chen''s explicit statement that the effect cannot be explained by changes in risk preference. The choice claiming Bayesian reasoning is unreliable regardless of stakes overgeneralizes; the passage specifically notes that participants did reason in a Bayesian manner when stakes were low.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EO2J8I', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the author of Text 1 most likely characterize the argument presented in Text 2?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EUASC3', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologists studying the coral reefs near Palau have documented a sharp decline in staghorn coral populations over the past eleven years. ________ the researchers have launched a restoration initiative that involves transplanting laboratory-grown coral fragments onto degraded sections of the reef.', $lyceon_json$[{"key":"A","text":"In response,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"For instance,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct transition is "In response," because the second sentence describes an action (a restoration initiative) taken as a direct reaction to the problem described in the first sentence (a decline in coral populations). "In contrast," incorrectly signals opposition between two ideas that are causally linked, not contrasting. "For instance," wrongly suggests the second sentence is an example of the decline, when it actually describes a remedial action. "Meanwhile," implies mere simultaneity rather than the cause-and-effect relationship evident in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EYQKKK', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly undermine the hypothesis presented in the text?', E'Cognitive psychologist Elaine Marchetti has proposed that the "spacing effect" — the well-documented phenomenon in which distributed practice leads to better long-term retention than massed practice — arises primarily from the increased cognitive effort required during spaced retrieval attempts. According to Marchetti, when learners revisit material after a delay, the partial forgetting that has occurred forces them to engage in deeper reconstructive processing, which strengthens memory traces more effectively than effortless re-reading. Marchetti cites several studies showing that participants who reported higher subjective difficulty during spaced retrieval sessions scored higher on delayed recall tests administered three weeks later.', $lyceon_json$[{"key":"A","text":"Participants who used spaced retrieval but were given strong contextual cues that eliminated retrieval difficulty showed retention gains equal to those of participants who experienced effortful spaced retrieval."},{"key":"B","text":"Massed practice sessions led to higher scores on immediate recall tests compared to spaced practice sessions, though the advantage disappeared within 24 hours."},{"key":"C","text":"Participants who engaged in spaced retrieval for verbal material showed larger spacing effects than those who practiced with visual material."},{"key":"D","text":"The spacing effect has been replicated across diverse populations, including children, older adults, and individuals with mild cognitive impairment."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the finding that participants given strong contextual cues — which eliminated retrieval difficulty — still showed equal retention gains from spaced retrieval. This directly undermines Marchetti''s hypothesis because her claim is that cognitive effort during retrieval is the primary driver of the spacing effect; if removing that effort produces the same benefit, the effort cannot be the primary cause. The finding about massed practice producing higher immediate but not delayed recall is consistent with the spacing effect generally but does not address whether cognitive effort specifically is the mechanism. The finding about verbal versus visual material differences concerns modality, not whether effort is the driving mechanism. The finding about replication across diverse populations supports the robustness of the spacing effect itself but says nothing about why it occurs, leaving Marchetti''s causal claim untested.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
