INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FCUMJ1', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Geochemist Aruna Patel has argued that volcanic eruptions in the Deccan Traps, not the Chicxulub asteroid impact, were the primary driver of the end-Cretaceous mass extinction. She points to evidence that toxic gas emissions from the eruptions began destabilizing ecosystems roughly 250,000 years before the asteroid struck. ________ Patel acknowledges that the asteroid impact likely intensified the extinction by compounding environmental stresses that the volcanic activity had already set in motion.', $lyceon_json$[{"key":"A","text":"By contrast,"},{"key":"B","text":"That said,"},{"key":"C","text":"Consequently,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct transition is "That said," because the final sentence introduces a concession: after arguing that volcanic eruptions were the primary cause, Patel concedes that the asteroid impact also played a role. "That said" signals this partial qualification without abandoning the original claim. "By contrast," implies the third sentence presents a wholly opposing view, but Patel is not reversing her position — she is acknowledging a contributing factor while maintaining her primary argument. "Consequently," suggests the third sentence is a logical result of the volcanic evidence, when it actually introduces a concession about a different cause. "Specifically," indicates elaboration or detail about a preceding point, but the final sentence broadens the discussion to include the asteroid rather than narrowing the focus on volcanic activity.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FQUPVX', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Geochemist Tomoko Saitō has proposed that the prevailing model of iron transport in deep ocean currents — which assumes iron primarily binds to organic ligands produced by phytoplankton — underestimates the role of colloidal mineral particles. In sediment trap analyses from seventeen stations across the North Pacific, Saitō found that between 38 and 54 percent of dissolved iron at depths below 2,000 meters was associated with inorganic colloids rather than organic ligands. While Saitō acknowledges that organic ligands remain important near the ocean surface, where phytoplankton are abundant, she contends that the dominant iron-binding mechanism shifts at depth, a distinction that current global ocean biogeochemistry models fail to capture. Other researchers, including geochemist Luís Ferreira, have noted that incorporating Saitō''s colloidal pathway into existing models could alter predictions of iron availability in deep-water upwelling zones by as much as 30 percent.', $lyceon_json$[{"key":"A","text":"Saitō's research indicates that inorganic colloids play a larger role in deep-ocean iron transport than prevailing models recognize, which could significantly affect predictions of iron availability."},{"key":"B","text":"Organic ligands produced by phytoplankton are the primary mechanism for iron transport throughout the entire ocean, a view that Saitō's work has confirmed with additional evidence."},{"key":"C","text":"Ferreira's response to Saitō's findings demonstrates that the scientific community is skeptical of revising established ocean biogeochemistry models."},{"key":"D","text":"Saitō's sediment trap analyses revealed that inorganic colloids are present at seventeen stations in the North Pacific, a finding that applies primarily to surface waters."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that Saitō''s research indicates inorganic colloids play a larger role in deep-ocean iron transport than models recognize, which could significantly affect iron availability predictions. The passage centers on Saitō''s challenge to the prevailing model and the potential implications, including Ferreira''s note about a 30 percent shift in predictions. The choice claiming Saitō confirmed that organic ligands are the primary mechanism throughout the ocean directly contradicts her argument: she contends the dominant mechanism shifts at depth. The choice characterizing the scientific community as "skeptical" misrepresents Ferreira, who suggests incorporating Saitō''s findings rather than rejecting them. The choice focusing on the seventeen stations and attributing the finding to surface waters misreads the passage, which specifies the colloidal iron was found at depths below 2,000 meters, not in surface waters.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KIVMJL', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'While writing about innovations in textile manufacturing, a student wants to acknowledge a limitation of bio-fabricated leather while emphasizing its potential to reduce the environmental costs of traditional leather production. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LDUTN3', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In her analysis of 14th-century Venetian trade ledgers, historian Priya Chandrasekaran uncovered evidence that merchant guilds employed a sophisticated double-entry bookkeeping system decades before Luca Pacioli''s celebrated 1494 _______ Pacioli''s treatise, long regarded as the origin of the practice, may instead represent a codification of techniques already widespread among Mediterranean traders.', $lyceon_json$[{"key":"A","text":"treatise, Pacioli's"},{"key":"B","text":"treatise, therefore, Pacioli's"},{"key":"C","text":"treatise, similarly, Pacioli's"},{"key":"D","text":"treatise. Pacioli's"}]$lyceon_json$::jsonb, 'D', NULL, E'A period correctly separates two independent clauses. The first clause establishes the historical finding—that guilds used double-entry bookkeeping before Pacioli''s 1494 treatise—and the second clause draws a conclusion about the treatise''s significance. The comma-only version ("treatise, Pacioli''s") creates a comma splice. The version with "therefore" misrepresents the logic: the second clause does not follow as a deductive consequence of the first but instead reinterprets the treatise''s role, and it also produces a comma splice by placing commas rather than a semicolon around the conjunctive adverb. The version with "similarly" is logically wrong because the second clause does not describe a parallel situation—it offers a recharacterization—and likewise produces a comma splice. The extra difficulty arises from the long, complex first clause and the intervening non-essential phrase "long regarded as the origin of the practice" in the second clause, which can obscure the sentence boundary.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LSTKE5', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare minerals housed in the Bancroft Museum _______ visitors from around the world each year. Curators have expanded the exhibit to include specimens from seventeen countries.', $lyceon_json$[{"key":"A","text":"attract"},{"key":"B","text":"attracts"},{"key":"C","text":"have attracted"},{"key":"D","text":"are attracting"}]$lyceon_json$::jsonb, 'B', NULL, E'The singular verb "attracts" correctly agrees with the singular subject "collection." Although the prepositional phrases "of rare minerals" and "housed in the Bancroft Museum" contain plural nouns, these modify the subject without changing its number. The plural forms "attract," "have attracted," and "are attracting" all fail to agree with the singular subject "collection." The phrase "each year" further confirms that the simple present tense is appropriate, as the sentence describes a habitual, ongoing action.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LYLR0E', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In the mid-twentieth century, many economists assumed that higher wages would invariably lead workers to seek more hours of employment. However, labor researcher Priya Venkatesh challenged this view in a 2019 analysis of payroll data from 1,400 manufacturing firms across South Asia. Venkatesh found that once workers'' hourly wages rose above a certain threshold — roughly 2.7 times the regional median — a notable proportion of employees voluntarily reduced their weekly hours. Venkatesh argues that this pattern reflects a "sufficiency equilibrium," in which workers who feel adequately compensated begin to prioritize leisure, family obligations, or education over additional income.', $lyceon_json$[{"key":"A","text":"Venkatesh's research suggests that wage increases beyond a certain level can lead workers to choose fewer hours rather than more, contradicting a longstanding economic assumption."},{"key":"B","text":"Economists in the mid-twentieth century were uniformly wrong about the relationship between wages and labor supply."},{"key":"C","text":"Manufacturing workers in South Asia earn significantly less than the regional median wage, prompting Venkatesh to propose reforms."},{"key":"D","text":"The concept of a \"sufficiency equilibrium\" was first introduced by mid-twentieth-century labor economists but has only recently been validated."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that Venkatesh''s research suggests wage increases beyond a threshold can lead workers to choose fewer hours, contradicting a longstanding assumption. The passage introduces the older assumption, then presents Venkatesh''s contrary finding as the central point. The choice claiming mid-twentieth-century economists were "uniformly wrong" overstates the passage, which says "many economists" held the assumption without declaring them all incorrect. The choice about South Asian manufacturing workers earning below the median misreads the passage: the data concerns what happens when wages rise above a threshold, not that workers earn below the median. The choice attributing the "sufficiency equilibrium" concept to mid-twentieth-century economists contradicts the passage, which attributes it to Venkatesh.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M9D7E6', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The string quartet''s interpretation of Shostakovich''s Eighth Quartet, which critics have praised for its emotional depth and technical precision, _______ the ensemble''s growing reputation as one of the foremost chamber groups in the country. Several reviewers noted that the performance conveyed both the anguish and the defiance embedded in the composition.', $lyceon_json$[{"key":"A","text":"have bolstered"},{"key":"B","text":"bolstering"},{"key":"C","text":"bolster"},{"key":"D","text":"has bolstered"}]$lyceon_json$::jsonb, 'D', NULL, E'The singular verb "has bolstered" correctly agrees with the singular subject "interpretation." The intervening non-essential relative clause "which critics have praised for its emotional depth and technical precision" separates the subject from the verb and introduces plural nouns ("critics," "depth and precision") that may mislead a reader into selecting a plural verb form. The plural "have bolstered" incorrectly treats a nearby plural noun as the subject. The present participle "bolstering" is not a finite verb and cannot serve as the main predicate, producing an incomplete sentence. The bare plural "bolster" fails to agree with the singular subject. The present perfect tense is appropriate because the interpretation''s effect on the ensemble''s reputation is ongoing.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MTDOBJ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'A 2023 longitudinal study of 1,400 bilingual children in Montreal found that those who regularly switched between French and Tagalog scored higher on tasks measuring cognitive flexibility than monolingual peers. The researchers attributed this advantage to the constant mental effort of managing two grammatical systems. ________ a follow-up analysis revealed that the cognitive flexibility gains diminished when the children used the two languages in strictly separated contexts — speaking Tagalog only at home and French only at school — rather than intermingling them throughout the day.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"However,"},{"key":"C","text":"In particular,"},{"key":"D","text":"For example,"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct transition is "However," because the follow-up analysis introduces a complication that limits the initial finding: the cognitive advantage held only when the children intermingled languages, not when they kept them strictly separated. This is a genuine counterpoint to the preceding claim. "Furthermore," signals additional supporting evidence, but the third sentence qualifies the finding rather than reinforcing it. "In particular," would narrow or elaborate on the existing point, yet the third sentence introduces a new condition under which the advantage disappears — a restriction, not a specification. "For example," suggests the follow-up illustrates the cognitive flexibility advantage, when it actually identifies circumstances that undermine it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OBV7GP', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the main purpose of the text?', E'Critics who characterize algorithmic curation as merely a technical convenience overlook its epistemic consequences. When a recommendation engine selects which studies a researcher encounters, it does not simply save time — it constructs a disciplinary horizon. Fields adjacent to the researcher''s stated interests are systematically deprioritized, and anomalous findings that might prompt paradigm revision are filtered as noise. The result is not efficiency but a subtle form of intellectual enclosure, one that reinforces existing frameworks precisely when they most need challenge.', $lyceon_json$[{"key":"A","text":"To argue that algorithmic curation narrows researchers' intellectual exposure in ways that go beyond mere convenience."},{"key":"B","text":"To propose a specific alternative to algorithmic recommendation systems for academic researchers."},{"key":"C","text":"To summarize existing research on the psychological effects of information overload in academic settings."},{"key":"D","text":"To defend the use of algorithmic curation by explaining how it protects researchers from unreliable sources."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice about algorithmic curation narrowing intellectual exposure beyond mere convenience. The passage opens by criticizing the view that curation is only a convenience and proceeds to argue it creates "intellectual enclosure" by deprioritizing adjacent fields and filtering anomalous findings. The choice about proposing a specific alternative misreads the passage, which critiques the current system but never suggests a replacement. The choice about summarizing research on information overload misidentifies the passage''s purpose; it discusses narrowing of exposure rather than psychological overwhelm, and it presents an argument, not a research summary. The choice about defending algorithmic curation directly contradicts the passage''s critical stance, which frames curation as reinforcing frameworks that need challenge rather than protecting researchers.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PS79SU', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Astrocytes, a type of glial cell in the brain, were once thought to serve only a structural _______ recent studies have demonstrated that these cells actively modulate synaptic transmission, regulate blood flow to neural tissue, and may even participate in information processing.', $lyceon_json$[{"key":"A","text":"role, recent"},{"key":"B","text":"role; however, recent"},{"key":"C","text":"role; in addition, recent"},{"key":"D","text":"role, however, recent"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct choice uses a semicolon before the conjunctive adverb "however" and a comma after it, which is the standard way to join two independent clauses when the second clause contrasts with the first. The passage sets up a clear contrast: astrocytes were once thought to be merely structural, but recent research shows they perform active functions. The comma-only version ("role, recent") creates a comma splice. The version using "in addition" employs mechanically correct punctuation, but the conjunctive adverb is logically wrong—the second clause contradicts the earlier assumption rather than adding to it. The version with commas around "however" ("role, however, recent") produces a comma splice because a conjunctive adverb joining two independent clauses requires a semicolon before it, not merely a comma.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RNE0AX', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'The Sonoran Desert receives fewer than ten inches of rainfall annually, making it one of the driest regions in North America. <u>Yet the desert supports over 2,000 plant species, including the iconic saguaro cactus, which can store up to 200 gallons of water in its trunk.</u> Botanists attribute this surprising biodiversity to the plants'' specialized water-retention mechanisms, which have evolved over millions of years.', $lyceon_json$[{"key":"A","text":"It introduces a contrast between the desert's aridity and its biological richness."},{"key":"B","text":"It provides evidence that botanists have studied the Sonoran Desert extensively."},{"key":"C","text":"It argues that the saguaro cactus is the most important species in the Sonoran Desert."},{"key":"D","text":"It challenges the claim that the Sonoran Desert is one of the driest regions in North America."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice about introducing a contrast between aridity and biological richness. The underlined sentence begins with "Yet," signaling a shift from the preceding point about low rainfall to the surprising fact that 2,000 plant species thrive there. The choice about evidence for extensive botanical study misidentifies the rhetorical purpose; the sentence describes biodiversity, not research activity. The choice about the saguaro being the most important species overstates the passage, which calls it "iconic" but does not rank its importance. The choice about challenging the aridity claim misreads the passage: the sentence accepts the aridity and presents biodiversity as an unexpected coexistence, not a refutation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SBM2NZ', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Researchers at the Kimura Oceanographic Institute recently published findings on the migratory behavior of leatherback sea turtles. By attaching satellite transmitters to seventeen individuals over a three-year period, _______ turtles regularly deviate from the most direct routes between nesting and feeding grounds, suggesting that ocean currents and thermal gradients play a larger role in navigation than previously understood.', $lyceon_json$[{"key":"A","text":"it was demonstrated that the"},{"key":"B","text":"the demonstration revealed that the"},{"key":"C","text":"the researchers demonstrated that the"},{"key":"D","text":"a demonstration showed that the"}]$lyceon_json$::jsonb, 'C', NULL, E'The participial phrase "By attaching satellite transmitters to seventeen individuals over a three-year period" must be followed by the noun that performed the action of attaching. Only "the researchers" logically performed this action, so the correct choice places "the researchers" as the subject of the main clause. The passive construction "it was demonstrated" creates a dangling modifier because "it" did not attach the transmitters. Similarly, "the demonstration revealed" and "a demonstration showed" both produce dangling modifiers because an abstract noun like "demonstration" cannot perform the physical action described in the participial phrase.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SR51RB', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'While writing a research summary, a student wants to present the primary finding of Dr. Okafor''s study to an audience unfamiliar with entomology. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VJTQSF', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1847, the physician Ignaz Semmelweis noticed that mortality rates in the maternity ward staffed by medical students were nearly five times higher than in the ward staffed by midwives. He hypothesized that cadaveric particles carried on students'' hands were responsible. After instituting a mandatory handwashing protocol with chlorinated lime, mortality in the affected ward dropped from 18 percent to under 2 percent. Despite this dramatic result, Semmelweis''s colleagues dismissed his findings, and widespread adoption of antiseptic practices did not occur until decades later.', $lyceon_json$[{"key":"A","text":"It presents an observation, describes a hypothesis and its successful test, and then notes the hypothesis's initial rejection by the scientific community."},{"key":"B","text":"It compares two competing theories of disease transmission and evaluates which one proved more accurate over time."},{"key":"C","text":"It argues that Semmelweis's handwashing protocol was flawed and explains why his colleagues were justified in rejecting it."},{"key":"D","text":"It chronicles the complete history of antiseptic medicine from its origins through its modern applications."}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice describing an observation, a hypothesis with successful test, and initial rejection. The passage moves from Semmelweis''s observation of differing mortality rates, to his cadaveric-particle hypothesis, to the dramatic drop in mortality after handwashing, and finally to his colleagues'' dismissal. The choice about two competing theories misreads the passage, which presents only Semmelweis''s hypothesis and does not describe a rival theory. The choice claiming the protocol was flawed contradicts the passage, which states mortality dropped from 18 percent to under 2 percent, demonstrating clear success. The choice about a complete history of antiseptic medicine overstates the passage''s scope; it covers only Semmelweis''s specific experience and notes that wider adoption came later, without chronicling that later history.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X4KVID', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The archaeologists first excavated the burial mound in 2019 and _______ more than four hundred ceramic fragments before the regional government suspended the project in 2021. The fragments are now housed at the Carolan Institute for further analysis.', $lyceon_json$[{"key":"A","text":"recovered"},{"key":"B","text":"have recovered"},{"key":"C","text":"recovering"},{"key":"D","text":"recovers"}]$lyceon_json$::jsonb, 'A', NULL, E'The simple past tense "recovered" correctly parallels "excavated" in the compound predicate "excavated the burial mound... and recovered more than four hundred ceramic fragments." Both actions occurred within a completed past timeframe (2019–2021), which the simple past appropriately conveys. The present perfect "have recovered" is wrong because the action has a definite past endpoint ("before the regional government suspended the project in 2021"), making the simple past, not the present perfect, the correct choice. The present participle "recovering" is not a finite verb and cannot serve as the predicate of the clause, producing a sentence fragment. The simple present "recovers" is wrong in both tense and number, as the sentence describes completed past actions performed by plural "archaeologists."', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
