INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZL7T40', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Although the diplomat''s public speeches advocated for immediate intervention, her private memoranda reveal a more ________ stance: she urged the committee to delay action until the regional elections concluded, arguing that premature involvement could destabilize the fragile coalition government.', $lyceon_json$[{"key":"A","text":"circumspect"},{"key":"B","text":"belligerent"},{"key":"C","text":"redundant"},{"key":"D","text":"whimsical"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "circumspect." The passage contrasts the diplomat''s public advocacy for immediate action with her private urging to delay, indicating her private position was careful and cautious about potential consequences. "Circumspect" means wary and unwilling to take risks, which fits the described caution about destabilizing a coalition. "Belligerent" means hostile and eager to fight, which contradicts the diplomat''s private counsel for restraint and delay. "Redundant" means unnecessarily repetitive or superfluous, which is incoherent as a description of a diplomatic stance. "Whimsical" means playfully quaint or fanciful, which is incompatible with the serious geopolitical context of destabilizing a government.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
